const input = $json;

const clean = (value) => {
  if (value === undefined || value === null) {
    return null;
  }

  const result = String(value).trim();

  return result === ''
    ? null
    : result;
};

const contactId = clean(input.contact_id);
const title = clean(input.title);
const startAtRaw = clean(input.start_at);
const endAtRaw = clean(input.end_at);

if (!title) {
  throw new Error('title es obligatorio');
}

if (!startAtRaw) {
  throw new Error('start_at es obligatorio');
}

if (!endAtRaw) {
  throw new Error('end_at es obligatorio');
}

const startAt = new Date(startAtRaw);
const endAt = new Date(endAtRaw);

if (Number.isNaN(startAt.getTime())) {
  throw new Error(
    `start_at no es una fecha válida: ${startAtRaw}`
  );
}

if (Number.isNaN(endAt.getTime())) {
  throw new Error(
    `end_at no es una fecha válida: ${endAtRaw}`
  );
}

if (endAt.getTime() <= startAt.getTime()) {
  throw new Error(
    'end_at debe ser posterior a start_at'
  );
}

const allowedStatuses = [
  'scheduled',
  'confirmed',
  'cancelled',
  'completed',
  'no_show'
];

const status =
  clean(input.status) ?? 'scheduled';

if (!allowedStatuses.includes(status)) {
  throw new Error(
    `status inválido: ${status}`
  );
}

const allowedSources = [
  'manual',
  'ai',
  'system'
];

const source =
  clean(input.source) ?? 'ai';

if (!allowedSources.includes(source)) {
  throw new Error(
    `source inválido: ${source}`
  );
}

return [
  {
    json: {
      appointment: {
        contact_id: contactId,
        title,

        start_at: startAt.toISOString(),
        end_at: endAt.toISOString(),

        status,

        notes: clean(input.notes),

        source,

        external_provider:
          clean(input.external_provider),

        external_event_id:
          clean(input.external_event_id)
      }
    }
  }
];

const appointment = $json.data;

if (!appointment?.id) {
  throw new Error(
    'Directus no devolvió appointment.id'
  );
}

return [
  {
    json: {
      status: 'created',
      appointment
    }
  }
];
